using MediDesk.Business.Interfaces; using MediDesk.Common.Contracts.Catalog; using MediDesk.Common.Contracts.Finance; namespace MediDesk.Business.Services; public sealed class SchemeService(ISchemeRepository r):ISchemeService {public Task<PagedResponse<SchemeDto>> GetPageAsync(SchemeQuery q,CancellationToken ct)=>r.GetPageAsync(q with{Search=q.Search?.Trim(),Page=Math.Max(1,q.Page),PageSize=Math.Clamp(q.PageSize,1,200)},ct);public Task<SchemeDto>CreateAsync(CreateSchemeRequest x,long u,CancellationToken ct)=>r.CreateAsync(x with{Name=x.Name.Trim(),AppliesTo=x.AppliesTo.Trim(),SchemeType=x.SchemeType.Trim()},u,ct);public Task<SchemeWriteResult>UpdateAsync(long id,UpdateSchemeRequest x,long u,CancellationToken ct)=>r.UpdateAsync(id,x with{Name=x.Name.Trim(),AppliesTo=x.AppliesTo.Trim(),SchemeType=x.SchemeType.Trim()},u,ct);public Task<bool>DeleteAsync(long id,long u,CancellationToken ct)=>r.SoftDeleteAsync(id,u,ct);}

